package com.example.notes;

import java.util.UUID;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;
import ru.vikulinva.usecase.UseCaseDispatcher;
import ru.vikulinva.usecase.UseCaseHandler;

@Component
@RequiredArgsConstructor
public class CreateNoteCommandHandler implements UseCaseHandler<CreateNoteCommand, UUID> {
  private final UseCaseDispatcher dispatcher;

  @Override
  public Class<CreateNoteCommand> useCaseType() {
    return CreateNoteCommand.class;
  }

  @Override
  @Transactional
  public UUID handle(CreateNoteCommand command) {
    return dispatcher.dispatch(new OtherCommand());
  }
}

